function weddingPrepRemainingMs(m){const p=m&&m.preparation||{},done=Math.max(0,+p.done||0),total=Math.max(done+1,+p.total||WEDDING_PREP_TOTAL),elapsed=Math.max(0,Date.now()-(+p.startedAt||Date.now()));if(done<=0)return Math.max(60000,+p.estimateMs||WEDDING_PREP_DEFAULT_MS);const average=Math.max(25000,elapsed/done);return Math.max(15000,average*(total-done));}
