async function weddingInvitationIntroLine(c,opt){opt=opt||{};const style=opt.style==='chinese'?'中式':opt.style==='modern'?'现代':'现代或中式',fallback='今天是七夕。我为我们准备了一场订婚宴，想和你一起选定它的模样。请柬就在下面，等你打开。';let text=fallback;try{const prompt='今天是七夕。你准备在微信里亲自邀请恋人参加你为你们两个人准备的现实订婚宴，下一张卡片会让她选择现代或中式形式。请严格按你本人的人设、关系、记忆和说话习惯，写一条20到65字的私人邀请话。硬性要求：必须明确说出“七夕”和“订婚宴”；必须全程站在你自己的第一人称角度，用“我”称呼自己、用“你”称呼恋人，并表达这是“我为我们准备的订婚宴”；自然承接下一张可点击请柬。禁止把自己说成“你的新郎”“新郎”“他”或直接用自己的名字代替“我”，禁止旁白、第三人称动作、括号动作、JSON、标签、Markdown、卡片格式，也不要提系统、程序、模型或生成。只输出一条普通微信正文。';const raw=await chatAPI([{role:'system',content:buildSystem(c)},{role:'user',content:prompt}],{max:180,temp:.78,complete:true}),cleaned=String(typeof roleVisibleEnvelopeText==='function'?roleVisibleEnvelopeText(raw):raw||'').replace(/```[\s\S]*?```/g,'').replace(/\[[^\]]*\]|【[^】]*】/g,'').replace(/[{}<>]/g,'').replace(/\s+/g,' ').trim(),valid=cleaned.length>=12&&cleaned.includes('七夕')&&cleaned.includes('订婚宴')&&/[我咱]/.test(cleaned)&&!/(你的新郎|新郎在|他在等|他为你|角色|旁白)/.test(cleaned)&&!/["']?(?:role|type|content|phase|json)["']?\s*[:：]/i.test(cleaned);if(valid)text=cleaned.slice(0,96);}catch(_){}return text;}
function weddingSendInvitationPersonalized(c,source,opt){if(!weddingEligibleRole(c))return false;const key='invite_intro_'+(source||'manual')+'_'+c.id;if(weddingInviteJobs[key])return false;weddingInviteJobs[key]=true;(async()=>{try{const text=await weddingInvitationIntroLine(c,opt),line={role:'assistant',type:'text',content:text,id:uid(),time:Date.now(),_weddingInviteIntro:true,_weddingStyle:opt&&opt.style||''};msgs(c.id).push(line);save();try{notifyIncoming(c,line);}catch(_){}const m=weddingSendInvitation(c,source,opt);if(m){m.introMessageId=line.id;save();}}finally{delete weddingInviteJobs[key];}})();return true;}
function weddingScheduleCalendarEvent(e){if(!e||e.type!=='wedding'||!e.contactId||!S.couple||e.contactId!==S.couple.cid)return false;const c=getC(e.contactId);if(!weddingEligibleRole(c))return false;const at=Number.isFinite(+e.eventAt)?+e.eventAt:new Date(e.date+'T'+(e.time||'19:00')+':00').getTime();if(!Number.isFinite(at))return false;let m=e.weddingInviteId&&msgs(c.id).find(x=>x&&x.id===e.weddingInviteId&&x.type==='weddinginvite');if(!m){m=weddingSendInvitation(c,'calendar',{eventAt:at,eventDate:e.date,calendarEventId:e.id});if(!m)return false;e.weddingInviteId=m.id;e.weddingInviteSentAt=Date.now();save();}return true;}
