function weddingAutoInvitation(at,preferred){const st=weddingState();if(st.invitation.autoSentAt||weddingLocalDay(at)<WEDDING_RELEASE_DAY)return false;const c=weddingInvitationRole(preferred);if(!c)return false;return weddingSendInvitationPersonalized(c,'auto',{eventAt:WEDDING_EVENT_AT});}
function weddingResetQixiInvitationOnce(){const st=weddingState(),reset='v985-qixi-engagement';if(st.invitation.qixiReset===reset)return false;st.invitation.qixiReset=reset;st.invitation.autoSentAt=0;for(const c of weddingRoles())for(const m of msgs(c.id)){if(!m||m.type!=='weddinginvite'||m.source!=='auto'||m.phase==='ready')continue;m.cancelledAt=m.cancelledAt||Date.now();m.supersededAt=m.supersededAt||Date.now();}save();return true;}
function weddingInviteRequest(text){const t=String(text||'').replace(/\s+/g,'');return /(?:发|给|来|补|重发|再发).{0,8}(?:婚礼|结婚).{0,6}(?:邀请|请柬)|(?:婚礼|结婚).{0,6}(?:邀请|请柬).{0,8}(?:发|给|要|想要|再来)|邀请我.{0,6}(?:参加|进入|去).{0,6}(?:婚礼|结婚)/.test(t);}
