async function weddingLoadPreparedScenes(c,prepared){const style=weddingStyleKey(prepared.style),order=weddingSceneOrder(style),scenes=weddingScenes(style),generationId=prepared.generationId||'first';if(W.generationId===generationId&&order.every(scene=>W.sceneImages[scene]))return true;W.generationId=generationId;W.sceneImages={};W.sceneJobs={};W.sceneVerify={};W.sceneFailures={};const previews=new Set(Array.isArray(prepared.previewScenes)?prepared.previewScenes:prepared.usesPreview?order:[]);for(const scene of order){if(previews.has(scene)||!weddingImageReady()){W.sceneImages[scene]=scenes[scene];continue;}const key=prepared.sceneKeys&&prepared.sceneKeys[scene]||weddingSceneKey(c,scene,prepared.script.formalwear,prepared.generationId,style),cached=typeof imgGet==='function'?await imgGet(key):null;if(!cached){W.sceneImages[scene]=scenes[scene];previews.add(scene);continue;}W.sceneImages[scene]=cached.src||cached;W.sceneVerify[scene]=cached.verified||{pass:true,reason:'缓存'};}prepared.previewScenes=Array.from(previews);return true;}
async function weddingEnterPrepared(c,m,prepared,simulation){if(W.busy)return;W.busy=true;const loaded=await weddingLoadPreparedScenes(c,prepared);W.busy=false;if(!loaded){weddingRegenerate(c.id,prepared.style||'modern');return toast('本地画面不完整，已在后台重新准备，不会进入空白婚礼');}m.openedAt=m.openedAt||Date.now();save();const style=weddingStyleKey(prepared.style);W.opening=true;W.session={cid:c.id,style,script:prepared.script,index:0,items:weddingBuildItems(prepared.script,!!simulation,style),choices:{},generated:prepared.generated,formalwear:prepared.script.formalwear,startedAt:Date.now(),ceremonyAt:m.eventAt,invitationId:m.preparedId||m.id,simulation:!!simulation,brideName:S.me&&S.me.name||'我',groomName:weddingRoleOriginalName(c)};const st=weddingState();if(!simulation){st.lastCid=c.id;save();}weddingShowNameCard(c);}
async function weddingOpenReadyInvite(cid,mid){const c=getC(cid),m=weddingEnsureInviteFormat(msgs(cid).find(x=>x&&x.id===mid&&x.type==='weddinginvite'));if(!weddingEligibleRole(c)||!m)return toast('婚礼只能与情侣空间绑定的角色进行');if(m.supersededAt)return toast('这张邀请已被新生成的婚礼覆盖，请打开最新卡片');const prepared=weddingState().prepared[m.preparedId];if(!prepared){weddingRegenerate(cid,m.style||'modern');return toast('原婚礼素材不完整，已在后台重新准备');}return weddingEnterPrepared(c,m,prepared,false);}
function weddingInvitationTick(){document.querySelectorAll('[data-wedding-countdown]').forEach(el=>{const at=+el.getAttribute('data-wedding-countdown');el.textContent=Date.now()>=at?'婚礼时间已到':weddingCountdownText(at);});document.querySelectorAll('[data-wedding-preparing]').forEach(el=>{const mid=el.getAttribute('data-wedding-preparing'),c=weddingInvitationRole(),m=c&&msgs(c.id).find(x=>x&&x.id===mid);if(m)el.textContent=weddingPrepTimeText(m);});for(const c of weddingRoles())for(const m of msgs(c.id)){if(!m||m.type!=='weddinginvite'||!m.preparedAt||m.readySentAt||Date.now()<m.eventAt)continue;weddingFinalizeInvitation(c,m);}}
function weddingResumeInvitations(){let repaired=false;for(const c of weddingRoles())for(const raw of msgs(c.id)){if(!raw||raw.type!=='weddinginvite')continue;const before=[raw.schema,raw.phase,raw.id,raw.eventAt].join('|'),m=weddingEnsureInviteFormat(raw);if(before!==[m.schema,m.phase,m.id,m.eventAt].join('|'))repaired=true;if(m.cancelledAt||m.supersededAt)continue;if(m.phase==='ready'&&!weddingState().prepared[m.preparedId]){m.phase='preparing';m.readySentAt=0;m.preparedAt=0;m.eventAt=Date.now();repaired=true;}if((m.phase==='preparing'||m.phase==='scheduled')&&!m.readySentAt){const prepared=weddingState().prepared[m.id];if(prepared){m.preparedAt=m.preparedAt||prepared.preparedAt;const readyAt=(+m.preparedAt||Date.now())+WEDDING_READY_DELAY_MS;if(!m.eventAt||m.eventAt>readyAt){m.requestedEventAt=+m.eventAt||0;m.eventAt=readyAt;m.eventDate=weddingLocalDay(readyAt);m.phase='scheduled';repaired=true;}weddingFinalizeInvitation(c,m);}else weddingPrepareInvitation(c,m);}}if(repaired)save();weddingInvitationTick();}

function weddingFitCertificateTitle(){const title=document.querySelector('.wedding-cert-content h2'),content=document.querySelector('.wedding-cert-content');if(!title||!content)return;title.style.width='max-content';title.style.maxWidth='none';title.style.transform='none';let size=Math.min(27,parseFloat(getComputedStyle(title).fontSize)||27),max=Math.max(180,content.clientWidth-18);title.style.fontSize=size+'px';while(size>18&&title.getBoundingClientRect().width>max){size-=.5;title.style.fontSize=size+'px';}title.style.width='100%';title.style.maxWidth='100%';title.style.textAlign='center';title.style.marginLeft='auto';title.style.marginRight='auto';}
function weddingOpen(cid,source){try{if(typeof audioUnlock==='function')audioUnlock();}catch(_){}W.view='setup';W.session=null;W.busy=false;const st=weddingState();W.selectedCid=cid||st.lastCid||((S.couple&&S.couple.cid)||'');const roles=weddingRoles();if(!roles.some(c=>c.id===W.selectedCid))W.selectedCid=roles[0]&&roles[0].id||'';W.entrySource=source||'app';weddingRenderSetup();}
function weddingClose(){clearTimeout(W.typingTimer);clearTimeout(W.sceneTimer);W.typingTimer=0;W.stageReady=false;W.scene='';weddingMusicStop();const root=weddingRoot();if(root)root.remove();}
function weddingRenderSetup(){const roles=weddingRoles(),imageReady=weddingImageReady(),disabled=!W.selectedCid?' disabled':'',simulate=weddingPrivateApp()?'<div class="wedding-style-starts wedding-style-simulations"><button class="wedding-start wedding-simulate-start"'+disabled+' onclick="weddingStart(\'simulation\',\'modern\')">模拟现代</button><button class="wedding-start wedding-simulate-start chinese"'+disabled+' onclick="weddingStart(\'simulation\',\'chinese\')">模拟中式</button></div><div class="wedding-simulate-note">两种模拟都不收藏婚书、不写记忆、不改变关系、不发送婚后消息；没有已完成内容时会先转入后台准备</div>':'';weddingMount('<section class="wedding-setup"><div class="wedding-setup-head"><button class="wedding-icon-btn" onclick="weddingClose()" aria-label="退出">‹</button><span></span></div><div class="wedding-kicker">OUR WEDDING · PRIVATE</div><h1>此刻，只属于你们</h1><p class="wedding-setup-lead">选择现代或中式；后台一次性完成整套台词和六幕画面，全部准备好后角色再发来可直接进入的邀请卡。</p><div class="wedding-role-title"><b>选择婚礼对象</b><span>全程纯点击字幕</span></div><div class="wedding-role-list">'+(roles.length?roles.map(c=>'<button class="wedding-role '+(c.id===W.selectedCid?'on':'')+'" onclick="weddingSelectRole(\''+c.id+'\')">'+av(c.avatar,'sm')+'<span class="wedding-role-copy"><b>'+esc(weddingRoleName(c))+'</b><small>纯字幕 · 点击继续</small></span><span class="wedding-role-check">✓</span></button>').join(''):'<div class="empty" style="padding:28px 10px">先在情侣空间绑定一个角色，才能准备婚礼。</div>')+'</div><div class="wedding-style-starts"><button class="wedding-start"'+disabled+' onclick="weddingStart(\'prepare\',\'modern\')">后台准备现代</button><button class="wedding-start chinese"'+disabled+' onclick="weddingStart(\'prepare\',\'chinese\')">后台准备中式</button></div>'+simulate+'<div class="wedding-setup-note">'+(imageReady?'预计约 11 分钟；某一幕失败会只重试该幕，仍失败才使用对应预置图。':'无需等待生图：将直接装入六张动作一致的预置演出图，仍会先把整场内容准备完整。')+'</div></section>');}
function weddingSelectRole(cid){W.selectedCid=cid;weddingRenderSetup();}
function weddingShowNameCard(c){const s=W.session;if(!s)return;const chinese=s.style==='chinese',title=chinese?'良辰既定 · 共书婚名':'Before We Begin',sub=chinese?'请写下今日婚书上的名字':'Write the names that will appear on your certificate';weddingMount('<section class="wedding-name-screen '+(chinese?'chinese':'modern')+'"><div class="wedding-name-glow"></div><div class="wedding-name-card"><small>'+(chinese?'CHINESE WEDDING':'OUR WEDDING')+'</small><h2>'+title+'</h2><p>'+sub+'</p><label><span>新娘</span><input id="weddingBrideName" maxlength="20" value="'+esc(s.brideName)+'" placeholder="你的名字"></label><label><span>新郎</span><input id="weddingGroomName" maxlength="20" value="'+esc(s.groomName)+'" readonly></label><button onclick="weddingBeginCeremony()">'+(chinese?'入喜堂':'进入仪式')+'</button><em>'+(s.simulation?'模拟模式 · 本次不会保存':'名字只用于本次婚礼与婚书')+'</em></div></section>');}
function weddingBeginCeremony(){const s=W.session,c=s&&getC(s.cid);if(!s||!c)return weddingClose();const bride=document.getElementById('weddingBrideName');s.brideName=weddingSafeText(bride&&bride.value,s.brideName||'我',20);s.groomName=weddingRoleOriginalName(c);try{if(typeof audioUnlock==='function')audioUnlock();}catch(_){}weddingMusicPlay(true);W.opening=true;W.stageReady=false;W.scene='';weddingRenderStory();}

function weddingFallback(c){const n=weddingRoleName(c);return{formalwear:'black',opening_narration:'玻璃穹顶映着晚霞，花瓣沿着长廊轻轻落下。人群安静下来，只有'+n+'朝你伸出手。',opening_line:'别看别人。今天，你只需要看着我。',hand_prompt:'走到他面前时，你想怎样把手交给他？',hand_choices:[{text:'握紧他的手，轻声说“我来了”',response:'嗯，我等到你了。这一次，我不会再松开。'},{text:'故意停住，问他会不会后悔',response:'会紧张，会害怕，但唯独不会后悔选择你。'}],aisle_narration:'你们牵着手走过铺满白色花瓣的长廊。乐声很轻，他的拇指始终安抚似的摩挲着你的指节。',aisle_line:'慢一点也没关系。我们有一辈子的时间。',officiant_line:'请你们看着彼此，回答这一生最郑重的问题：无论顺境或低谷，是否愿意继续选择对方？',vow_prompt:'轮到你回答誓言时，你想对他说什么？',vow_choices:[{text:'“我愿意，也愿意一直偏爱你。”',response:'这句话我会记一辈子。以后换我一次次证明给你看。'},{text:'“不只今天，以后的每一天都愿意。”',response:'好。那以后每一天醒来，我都重新向你求一次婚。'}],vow_narration:'他双手拿着展开的誓词纸，正面望着你。开口前停了两秒，仍然没有移开目光。',vow_line:'我不能许诺生活永远平静，但我许诺每一次风雨里，我都会站在你这一边。',kiss_narration:'他托住你的指尖，俯身在你的手背落下一个很轻、很郑重的吻。掌心的温度沿着指节传来。',kiss_line:'这个吻不是礼节，是我把余生交给你的证明。',ring_prompt:'戒指就在他掌心，你想让这一刻怎样继续？',ring_choices:[{text:'先替他戴上戒指',response:'原来被你套牢的感觉，是这样。很好，我很喜欢。'},{text:'向他伸出左手',response:'交给我。我会戴得很慢，让你记住这一秒。'}],ring_narration:'他把戒指缓缓戴过你左手的指尖，停在无名指上。银色边缘接住灯光，也接住四周的掌声。',ring_line:'戴上以后，就不许假装今天只是一场梦。',blessing_narration:'亲友的祝福从四周涌来。有人笑着鼓掌，也有人悄悄擦去眼泪，而他正面拥住你，仍只看着你。',blessing_line:'以往的故事到这里不是结局。从今天起，你们将共同书写往后的每一页。',ending_narration:'音乐重新响起，他拥着你走向长廊尽头。身后的花瓣落下，像替这一刻盖上温柔的印章。',ending_line:'走吧，新娘。我们的以后，现在开始。',certificate_vow:'愿往后的每一次欢笑与风雨，都有我在你身旁。'};}
function weddingJSON(raw){const t=String(raw||'').replace(/```json\s*/gi,'').replace(/```/g,'').trim(),a=t.indexOf('{'),b=t.lastIndexOf('}');if(a<0||b<=a)throw new Error('no-json');return JSON.parse(t.slice(a,b+1));}
function weddingLooksNarration(text){const t=String(text||'').replace(/\s+/g,' ').trim();if(!t)return false;if(/^[“"「『].+[”"」』]$/.test(t))return false;const thirdPerson=/(?:^|[，。；！？])(?:你|他|她|两人|你们|人群|宾客|司仪|音乐|花瓣|灯光|掌声|长廊|玻璃穹顶)/.test(t),action=/(?:目光|视线|指尖|掌心|脚步|声音|呼吸|神情|眉眼|唇角|停了|落下|抬起|低下|俯身|走近|握住|牵住|托住|戴上|拥住|看着|望着|念|摩挲|轻颤|响起|安静下来)/.test(t),selfVoice=/^(?:我|别|今天|以后|这一次|交给我|慢一点|走吧|好[，。]|嗯[，。]|愿|请你|嫁给我|答应我)/.test(t);return !selfVoice&&thirdPerson&&action;}
function weddingNormalizeChoices(raw,fallback){const list=Array.isArray(raw)?raw:[];return[0,1].map(i=>{const response=weddingSafeText(list[i]&&list[i].response,fallback[i].response,82);return{text:weddingSafeText(list[i]&&list[i].text,fallback[i].text,34),response:weddingLooksNarration(response)?fallback[i].response:response};});}
function weddingLineMatchesScene(field,text){const scene=WEDDING_FIELD_SCENES[field],t=String(text||'');if(!scene)return true;const forbidden={welcome:/戒指|无名指|亲吻|吻.{0,3}手背|拥抱|誓词纸/,aisle:/吻.{0,3}手背|亲吻|无名指|戴.{0,3}戒指|誓词纸|拥抱/,vow:/无名指|戴.{0,3}戒指|亲吻|吻.{0,3}手背|拥抱/,kiss:/无名指|戴.{0,3}戒指|拥抱|誓词纸/,ring:/亲吻|吻.{0,3}手背|拥抱|誓词纸/,embrace:/戴.{0,3}戒指|无名指|吻.{0,3}手背|誓词纸/};if(forbidden[scene]&&forbidden[scene].test(t))return false;if(field==='kiss_narration'&&!/手背/.test(t))return false;if(field==='ring_narration'&&(!/戒指/.test(t)||!/无名指/.test(t)))return false;if(field==='vow_narration'&&!/(双手|两手).{0,8}(誓词|纸)|(?:誓词|纸).{0,8}(双手|两手)/.test(t))return false;return true;}
function weddingNormalize(data,c){const f=weddingFallback(c),out={},fields=['opening_narration','opening_line','hand_prompt','aisle_narration','aisle_line','officiant_line','vow_prompt','vow_narration','vow_line','kiss_narration','kiss_line','ring_prompt','ring_narration','ring_line','blessing_narration','blessing_line','ending_narration','ending_line','certificate_vow'];fields.forEach(k=>{const value=weddingSafeText(data&&data[k],f[k],k.includes('narration')||k==='certificate_vow'?120:k.includes('prompt')||k.includes('officiant')||k.includes('blessing_line')?90:76);out[k]=weddingLineMatchesScene(k,value)?value:f[k];});const pairs=[['opening_line','opening_narration'],['aisle_line','aisle_narration'],['officiant_line','aisle_narration'],['vow_line','vow_narration'],['kiss_line','kiss_narration'],['ring_line','ring_narration'],['blessing_line','blessing_narration'],['ending_line','ending_narration']];for(const [lineKey,narrationKey] of pairs){if(!weddingLooksNarration(out[lineKey]))continue;const moved=weddingSafeText(out[narrationKey]+' '+out[lineKey],out[narrationKey],150);if(weddingLineMatchesScene(narrationKey,moved))out[narrationKey]=moved;out[lineKey]=f[lineKey];}const fw=String(data&&data.formalwear||'').toLowerCase();out.formalwear=/white|ivory|白/.test(fw)?'white':/black|黑/.test(fw)?'black':f.formalwear;out.hand_choices=weddingNormalizeChoices(data&&data.hand_choices,f.hand_choices);out.vow_choices=weddingNormalizeChoices(data&&data.vow_choices,f.vow_choices);out.ring_choices=weddingNormalizeChoices(data&&data.ring_choices,f.ring_choices);return out;}
async function weddingGenerate(c){const contracts=WEDDING_SCENE_ORDER.map(k=>'【'+WEDDING_SCENE_CONTRACTS[k].title+'】'+WEDDING_SCENE_CONTRACTS[k].must+'；'+WEDDING_SCENE_CONTRACTS[k].forbid).join('\n');const prompt='你正在与“'+(S.me&&S.me.name||'我')+'”举行一场完整的现代婚礼。用户是新娘，所有关键画面采用新娘第一人称视角。请严格依据你已有的人物设定、说话习惯、真实关系与记忆写婚礼互动。必须同时包含客观细腻的旁白、司仪台词和你本人说出的台词。台词与对应画面必须完全对口，不能提前或滞后描述其他动作。\n'+contracts+'\n礼服规则：忽略人物设定中的所有日常穿搭。请根据人物气质在正式黑色新郎礼服与正式象牙白新郎礼服中自行选择一种，并在 formalwear 字段只写 black 或 white；整场婚礼固定这一套，不得中途换色。固定流程：伸手迎接、牵手花路、司仪询问、双方誓言、亲吻手背、交换戒指、礼成拥抱、签署婚书。旁白不得冒充角色说话，角色台词不得写成旁白。所有 narration 字段只写第三人称或环境旁白；所有 line 与 choices.response 字段只能写角色亲口说出的原话，禁止出现“他看着你、他的目光、他低下头、声音比平时更低”等第三人称动作描写；officiant_line 与 blessing_line 只能写司仪亲口说的话。不要提系统、网页、模型、按钮或设定，不输出任何控制标签或 Markdown。只输出一个 JSON 对象，字段完整：formalwear, opening_narration, opening_line, hand_prompt, hand_choices（恰好两个对象，每个含 text 和 response）, aisle_narration, aisle_line, officiant_line, vow_prompt, vow_choices（恰好两个对象）, vow_narration, vow_line, kiss_narration, kiss_line, ring_prompt, ring_choices（恰好两个对象）, ring_narration, ring_line, blessing_narration, blessing_line, ending_narration, ending_line, certificate_vow。旁白24到60字，角色台词10到45字，选择文字不超过24字。certificate_vow 只写一句25到55字、符合你说话习惯的专属婚书结语。';const raw=await chatAPI([{role:'system',content:buildSystem(c)},{role:'user',content:prompt}],{aux:!!(S.settings&&S.settings.gameUseAux),max:2400,temp:.78,complete:true});return weddingNormalize(weddingJSON(raw),c);}

function weddingChineseFallback(c){const n=weddingRoleName(c);return{formalwear:'red',opening_narration:'花轿停在喜堂门前，帘外锣鼓渐歇。红帘被轻轻挑开，'+n+'俯身望向你，朝你递来手。',opening_line:'良辰已至。把手给我，我接你下轿。',hand_prompt:'红帘之外，他仍等着你的回应。',hand_choices:[{text:'把手郑重交给他',response:'慢些走。有我在，今日往后都不会让你独行。'},{text:'隔着红帘轻声唤他',response:'我在。你唤一声，我便应你一生。'}],silk_narration:'你与他各执红绣球的一端，并肩步入灯火通明的喜堂。红绸在两人之间轻轻晃动，像牵住了往后的岁月。',silk_line:'这一端我握紧了，余生也不会松。',heaven_officiant:'一拜天地——',heaven_narration:'他转向喜堂正前方，与你一同俯身，敬天地为证。',heaven_line:'天地既鉴，此心此诺，永不相负。',high_officiant:'二拜高堂——',high_narration:'同一盏烛火映着他的侧脸。你们再次俯身，敬来路、敬亲恩，也敬此后共同的家。',high_line:'今日承亲恩成礼，往后我会护好我们的家。',couple_officiant:'夫妻对拜——',couple_narration:'他转身面向你，隔着红绸郑重俯首。四周喧声渐远，只余你们彼此这一拜。',couple_line:'这一拜，不止今日。往后晨昏岁岁，我都与你相对。',toast_narration:'喜堂烛影摇红，你们各自举起金色酒杯，在彼此面前轻轻相碰。',toast_line:'以此杯敬你，也敬我们此后同心同归。',veil_narration:'夜色渐深，你坐在铺着红锦的婚床上。他执起喜秤，让顶端轻轻托住盖头前缘，缓缓向上挑起。',veil_line:'今日终于能好好看你。夫人，往后请多指教。',ending_narration:'红盖头落在一旁，烛火将你们的影子映在一起。礼数至此圆满，新的岁月也从此刻启程。',ending_line:'礼成了。你我一诺，此生作数。',certificate_vow:'愿与你白首同心，朝朝暮暮相守，岁岁年年不负。'};}
function weddingChineseNormalize(data,c){const f=weddingChineseFallback(c),out={formalwear:'red'},fields=['opening_narration','opening_line','hand_prompt','silk_narration','silk_line','heaven_officiant','heaven_narration','heaven_line','high_officiant','high_narration','high_line','couple_officiant','couple_narration','couple_line','toast_narration','toast_line','veil_narration','veil_line','ending_narration','ending_line','certificate_vow'];for(const k of fields)out[k]=weddingSafeText(data&&data[k],f[k],k.includes('narration')||k==='certificate_vow'?130:82);out.hand_choices=weddingNormalizeChoices(data&&data.hand_choices,f.hand_choices);out.heaven_officiant='一拜天地——';out.high_officiant='二拜高堂——';out.couple_officiant='夫妻对拜——';return out;}
async function weddingGenerateChinese(c){const contracts=WEDDING_CHINESE_SCENE_ORDER.map(k=>'【'+WEDDING_CHINESE_SCENE_CONTRACTS[k].title+'】'+WEDDING_CHINESE_SCENE_CONTRACTS[k].must+'；'+WEDDING_CHINESE_SCENE_CONTRACTS[k].forbid).join('\n');const prompt='你正在与“'+(S.me&&S.me.name||'我')+'”举行一场现实中的中式婚礼。请严格依据你的人物性格、关系和记忆写偏古风但自然可懂的角色台词，同时写独立旁白。流程固定为：花轿内掀帘伸手迎新娘下轿、牵红绣球入喜堂、一拜天地、二拜高堂、夫妻对拜、双方碰杯敬酒、在婚床前用喜秤挑起新娘盖头、签中式婚书。拜堂顺序绝不能改变；一拜天地与二拜高堂使用同一张侧脸拜礼画面并多停留，夫妻对拜才切换下一张。\n'+contracts+'\n角色外形硬规则：忽略日常穿搭与现代发型，整场固定红色中式新郎喜服、黑色古风长发和传统发冠。旁白只写环境和第三人称动作；line 字段只能写角色亲口说的话，不得混入“他看着你”等动作。司仪三句固定。只输出 JSON：formalwear, opening_narration, opening_line, hand_prompt, hand_choices（两个对象，含 text,response）, silk_narration, silk_line, heaven_officiant, heaven_narration, heaven_line, high_officiant, high_narration, high_line, couple_officiant, couple_narration, couple_line, toast_narration, toast_line, veil_narration, veil_line, ending_narration, ending_line, certificate_vow。不要 Markdown、标签、系统说明。';const raw=await chatAPI([{role:'system',content:buildSystem(c)},{role:'user',content:prompt}],{aux:!!(S.settings&&S.settings.gameUseAux),max:2300,temp:.78,complete:true});return weddingChineseNormalize(weddingJSON(raw),c);}

function weddingAppearanceProfile(c,style){style=weddingStyleKey(style);const raw=[c&&c.imgLock,c&&c.persona].filter(Boolean).join('。').replace(/\s+/g,' '),parts=raw.split(/[。；;\n]/).map(x=>x.trim()).filter(Boolean),look=/发型|头发|刘海|发色|眼睛|瞳|眼型|眉|鼻|唇|嘴|脸|轮廓|肤色|皮肤|痣|雀斑|身高|肩|体型|年龄|成年|男性|气质/,clothes=/穿搭|日常穿|常穿|衣服|上衣|外套|卫衣|衬衫|毛衣|夹克|裙|牛仔|鞋|裤|领带|西装|礼服/,hair=/发型|头发|刘海|发色|短发|长发|金发|白发|银发|棕发|红发|蓝发/;let picked=parts.filter(x=>look.test(x)&&!clothes.test(x)&&(style!=='chinese'||!hair.test(x))).join('；');if(!picked)picked=parts.filter(x=>!clothes.test(x)&&(style!=='chinese'||!hair.test(x))).slice(0,2).join('；');const hairRule=style==='chinese'?'；发型按该角色气质独立设计，但强制为纯黑色古风长发并佩戴传统发冠，同一场六幕的具体束发结构、刘海分缝、发冠造型必须完全一致；不同角色可拥有不同长发造型和不同脸':'';return ('成年男性；'+(picked||'外貌严格依据该角色既有五官、肤色和体型')+hairRule+'；身份锚点 '+weddingHash((c&&c.id||'role')+'|'+raw+'|'+style)).slice(0,520);}
function weddingImageReady(){const ch=S.settings&&S.settings.chat||{},base=(S.settings&&S.settings.imgBase)||ch.base,key=(S.settings&&S.settings.imgKey)||ch.key;return !!(base&&key&&typeof imageGenerateExternal==='function');}
function weddingFormalwearText(v){return v==='white'?'象牙白色正式新郎礼服（ivory white formal groom tuxedo）':'黑色正式新郎礼服（black formal groom tuxedo）';}
function weddingBuildImagePrompt(c,scene,formalwear,extra,style){style=weddingStyleKey(style);const ct=weddingContracts(style)[scene]||weddingContracts(style)[weddingSceneOrder(style)[0]],identity=weddingAppearanceProfile(c,style),chinese=style==='chinese',wear=chinese?'固定红色中式新郎喜服（traditional red Chinese groom wedding robe）':weddingFormalwearText(formalwear);return ('竖版 2:3，精致高质量日系动漫插画，'+(chinese?'古代中式婚礼喜堂，红金烛火与传统婚俗氛围':'现代玻璃花房婚礼，柔和电影光线')+'，沉浸式视觉小说CG。\n【同一人物身份锁】'+identity+'。六张图必须是同一个成年男性，新郎的脸型、五官、肤色、瞳色、具体发型结构、发色、发冠和体型全程一致；不同角色的身份锚点不同，脸与发型设计必须随各自人设变化，绝不能套用同一张脸。\n【礼服与头发硬规则】整场固定穿'+wear+'。'+(chinese?'必须纯黑色古风长发、传统发冠、红色喜服；头发必须明显过肩，严禁短发、现代发型、非黑发和现代西装。完全忽略人物设定中的日常发型颜色与日常穿搭。':'只允许正式黑色或象牙白色新郎礼服，完全忽略人物设定中的日常穿搭。')+'\n【新娘视角硬规则】镜头就是新娘的眼睛。不得出现新娘正脸或第三人称全身；只在动作必要时出现镜头前的新娘手部、头纱或肩部边缘。\n【本张唯一动作】'+ct.action+'\n【必须看见】'+ct.must+'。\n【禁止】'+ct.forbid+' 不得多手、多指、错位肢体，不得出现文字、字幕、水印、Logo。画面必须只表达本张动作，不得偷跑下一幕。'+(extra?'\n【本张重试纠正与身份参考】'+extra+' 参考图是绝对身份标准：具体脸型、五官比例、刘海分缝、束发结构、每一缕长发、发冠外形与喜服纹样必须一模一样，只改变动作和镜头。':'')).slice(0,3500);}
function weddingSceneKey(c,scene,formalwear,generationId,style){style=weddingStyleKey(style);return '__wedding_cg_v7_'+weddingHash((c&&c.id||'')+'|'+weddingAppearanceProfile(c,style)+'|'+style+'|'+scene+'|'+formalwear+'|'+(generationId||W.generationId||'first'));}
async function weddingVerifyImage(src,c,scene,formalwear,referenceNote,style){style=weddingStyleKey(style);if(typeof visionAPI!=='function')return{pass:true,reason:'未配置视觉复核'};const ct=weddingContracts(style)[scene],chinese=style==='chinese';try{const raw=await visionAPI(src,'只做婚礼CG质检。检查：1）是否为成年男性新郎；2）是否穿'+(chinese?'固定红色中式新郎喜服，并且是纯黑色明显过肩古风长发、佩戴传统发冠，绝无短发、非黑发或现代西装':weddingFormalwearText(formalwear)+'且没有日常穿搭')+'；3）是否严格完成“'+ct.must+'”；4）是否违反“'+ct.forbid+'”；5）是否为新娘第一人称且不出现新娘正脸；6）手指和肢体是否明显错误。'+(referenceNote?'7）与同场参考必须是同一个人：脸型、五官比例、具体刘海分缝、束发结构、长发轮廓、发色、发冠造型、礼服领型与纹样都必须一模一样，不能只做到大致相似。参考摘要：“'+referenceNote+'”。':'')+'只输出 JSON：{"pass":true或false,"reason":"不通过时用一句中文说清最关键错误"}。'),d=weddingJSON(raw);return{pass:d.pass===true,reason:weddingSafeText(d.reason,'动作、身份或礼服未通过复核',120)};}catch(_){return{pass:true,reason:'视觉复核不可用'};}}
function weddingIdentityReference(scene,style){style=weddingStyleKey(style);const scenes=weddingScenes(style);for(const key of weddingSceneOrder(style)){const src=W.sceneImages[key],verified=W.sceneVerify[key];if(key===scene||!src||src===scenes[key]||verified&&verified.pass===false)continue;return{scene:key,src};}return null;}
async function weddingReferenceIdentityNote(ref,c,formalwear,style){style=weddingStyleKey(style);if(!ref||!ref.src||typeof visionAPI!=='function')return'';try{return weddingSafeText(await visionAPI(ref.src,'只描述图中成年男性新郎可用于保持连续镜头身份的稳定特征：脸型、眉眼、瞳色、鼻唇、肤色、刘海分缝、具体束发结构、长发轮廓、发色、发冠外形，以及'+(style==='chinese'?'红色中式喜服的领型与金色纹样':weddingFormalwearText(formalwear)+'的领型和固定细节')+'。不要描述动作、背景、新娘或画面质量；只输出一段80到180字中文。'),'同一位新郎的脸型、具体发型、发冠和礼服纹样必须与参考画面一模一样',220);}catch(_){return'';}}
async function weddingGenerateWithReference(base,key,model,prompt,referenceSrc){if(referenceSrc&&typeof imagePostCompat==='function'&&typeof imageResultURL==='function'){try{const out=await imagePostCompat(base,key,'/chat/completions',{model,messages:[{role:'user',content:[{type:'text',text:prompt+'\n\n第一张输入图是同一场婚礼已经通过复核的身份参考。必须复制其中新郎的脸型、五官、发型、发色与礼服，只改变本张规定的动作和镜头。请直接生成图片。'},{type:'image_url',image_url:{url:referenceSrc}}]}],max_tokens:1200},210000),url=out&&out.res&&out.res.ok?imageResultURL(out.d):'';if(url)return{url,endpoint:'chat-reference',model};}catch(_){}}
  return imageGenerateExternal(base,key,model,prompt,'1024x1536','high');}
async function weddingGenerateScene(c,scene,formalwear,opt){opt=opt||{};const style=weddingStyleKey(opt.style),contracts=weddingContracts(style),ch=S.settings&&S.settings.chat||{},base=((S.settings&&S.settings.imgBase)||ch.base||'').replace(/\/+$/,''),key=(S.settings&&S.settings.imgKey)||ch.key||'',model=(S.settings&&S.settings.imgModel)||'gpt-image-2';if(!base||!key)throw new Error('未配置生图接口');const reference=opt.reference||null,referenceNote=reference?await weddingReferenceIdentityNote(reference,c,formalwear,style):'',extra=[opt.reason||'',referenceNote&&('参考画面 '+contracts[reference.scene].title+' 的身份摘要：'+referenceNote+'。具体脸型、五官、发型结构、发冠和礼服必须一模一样。')].filter(Boolean).join(' '),prompt=weddingBuildImagePrompt(c,scene,formalwear,extra,style),result=reference?await weddingGenerateWithReference(base,key,model,prompt,reference.src):await imageGenerateExternal(base,key,model,prompt,'1024x1536','high'),src=await stableImageSrc(result.url),check=await weddingVerifyImage(src,c,scene,formalwear,referenceNote,style);W.sceneVerify[scene]=check;if(!check.pass){const err=new Error('动作复核未通过：'+(check.reason||scene));err.weddingReason=check.reason;throw err;}return src;}
function weddingPrepareScene(c,scene,formalwear,deferFallback,style){style=weddingStyleKey(style);const scenes=weddingScenes(style);if(W.sceneImages[scene])return Promise.resolve(W.sceneImages[scene]);if(W.sceneJobs[scene])return W.sceneJobs[scene];const job=(async()=>{if(!weddingImageReady()){W.sceneImages[scene]=scenes[scene];return W.sceneImages[scene];}const key=weddingSceneKey(c,scene,formalwear,W.generationId,style);try{const cached=typeof imgGet==='function'?await imgGet(key):null;if(cached){W.sceneImages[scene]=cached.src||cached;W.sceneVerify[scene]=cached.verified||{pass:true,reason:'缓存'};return W.sceneImages[scene];}const src=await weddingGenerateScene(c,scene,formalwear,{style});W.sceneImages[scene]=src;if(typeof imgPut==='function')await imgPut(key,{src,verified:W.sceneVerify[scene],createdAt:Date.now()});return src;}catch(e){W.sceneFailures[scene]=String(e&&e.weddingReason||e&&e.message||e).slice(0,160);W.sceneVerify[scene]={pass:false,reason:W.sceneFailures[scene]};if(deferFallback)return'';W.sceneImages[scene]=scenes[scene];return W.sceneImages[scene];}finally{delete W.sceneJobs[scene];}})();W.sceneJobs[scene]=job;return job;}
async function weddingRetryFailedScene(c,scene,formalwear,style){style=weddingStyleKey(style);const reference=weddingIdentityReference(scene,style),reason=W.sceneFailures[scene]||'第一次生成失败';try{const src=await weddingGenerateScene(c,scene,formalwear,{reference,reason,style});W.sceneImages[scene]=src;delete W.sceneFailures[scene];const key=weddingSceneKey(c,scene,formalwear,W.generationId,style);if(typeof imgPut==='function')await imgPut(key,{src,verified:W.sceneVerify[scene],createdAt:Date.now(),retried:true,referenceScene:reference&&reference.scene||''});return src;}catch(e){W.sceneImages[scene]=weddingScenes(style)[scene];W.sceneVerify[scene]={pass:false,reason:String(e&&e.weddingReason||e&&e.message||e).slice(0,160)};return W.sceneImages[scene];}}

function weddingMusicElement(style){const src=weddingBgm(style||W.session&&W.session.style);if(W.bgm&&W.bgm.getAttribute('data-wedding-src')===src)return W.bgm;if(W.bgm)weddingMusicStop();try{const a=new Audio(src);a.loop=true;a.preload='auto';a.volume=.34;a.setAttribute('data-wedding-src',src);a.setAttribute('playsinline','');a.setAttribute('webkit-playsinline','');W.bgm=a;return a;}catch(_){return null;}}
function weddingMusicPlay(reset){const a=weddingMusicElement();if(!a)return false;try{if(reset)a.currentTime=0;a.loop=true;a.volume=.34;const p=a.play();if(p&&p.catch)p.catch(()=>{});return true;}catch(_){return false;}}
function weddingMusicStop(){const a=W.bgm;if(!a)return;try{a.pause();a.currentTime=0;}catch(_){}W.bgm=null;}
async function weddingStartSimulation(cid,mid,style){if(!weddingPrivateApp())return;if(cid)W.selectedCid=cid;else if(!W.selectedCid)W.selectedCid=weddingInvitationRole()&&weddingInvitationRole().id||'';const c=getC(W.selectedCid);if(!weddingEligibleRole(c))return toast('婚礼只能与情侣空间绑定的角色进行');let m=mid&&msgs(c.id).find(x=>x&&x.id===mid&&x.type==='weddinginvite');style=weddingStyleKey(style||m&&m.style);if(!m||m.phase!=='ready'||m.supersededAt)m=weddingLatestReadyInvite(c,style);if(!m){weddingRegenerate(c.id,style);return toast('还没有准备完整的'+(style==='chinese'?'中式':'现代')+'婚礼，已转入后台生成；完成后再点模拟即可直接观看');}const prepared=weddingState().prepared[m.preparedId];if(!prepared)return weddingRegenerate(c.id,style);return weddingEnterPrepared(c,m,prepared,true);}
async function weddingStart(mode,style){if(W.busy||!W.selectedCid)return;style=weddingStyleKey(style);const c=getC(W.selectedCid);if(!weddingEligibleRole(c))return toast('婚礼只能与情侣空间绑定的角色进行');const ready=weddingLatestReadyInvite(c,style);if(mode==='simulation')return weddingStartSimulation(c.id,ready&&ready.id,style);if(ready){weddingClose();return weddingOpenReadyInvite(c.id,ready.id);}return weddingRegenerate(c.id,style);}
function weddingBuildItems(s,simulation,style){style=weddingStyleKey(style);if(style==='chinese')return[{kind:'narrator',scene:'sedan',text:s.opening_narration},{kind:'role',scene:'sedan',text:s.opening_line},{kind:'choice',id:'hand',scene:'sedan',text:s.hand_prompt,choices:s.hand_choices},{kind:'narrator',scene:'silk',text:s.silk_narration},{kind:'role',scene:'silk',text:s.silk_line},{kind:'ceremony',scene:'bow',speaker:'司礼',text:'一拜天地——'},{kind:'narrator',scene:'bow',text:s.heaven_narration},{kind:'role',scene:'bow',text:s.heaven_line},{kind:'ceremony',scene:'bow',speaker:'司礼',text:'二拜高堂——'},{kind:'narrator',scene:'bow',text:s.high_narration},{kind:'role',scene:'bow',text:s.high_line},{kind:'ceremony',scene:'couple',speaker:'司礼',text:'夫妻对拜——'},{kind:'narrator',scene:'couple',text:s.couple_narration},{kind:'role',scene:'couple',text:s.couple_line},{kind:'narrator',scene:'toast',text:s.toast_narration},{kind:'role',scene:'toast',text:s.toast_line},{kind:'narrator',scene:'veil',text:s.veil_narration},{kind:'role',scene:'veil',text:s.veil_line},{kind:'narrator',scene:'veil',text:s.ending_narration},{kind:'role',scene:'veil',text:s.ending_line},{kind:'finish',scene:'veil',text:simulation?'模拟礼成，所见只留在本次预览。':'三书已定，六礼既成，你们将共同落笔婚书。',label:simulation?'模拟共书婚约':'共同签下中式婚书'}];return[{kind:'narrator',scene:'welcome',text:s.opening_narration},{kind:'role',scene:'welcome',text:s.opening_line},{kind:'action',scene:'welcome',text:'他仍正面向你伸着手，指尖停在离你很近的地方。',label:'向他走过去'},{kind:'choice',id:'hand',scene:'welcome',text:s.hand_prompt,choices:s.hand_choices},{kind:'narrator',scene:'aisle',text:s.aisle_narration},{kind:'role',scene:'aisle',text:s.aisle_line},{kind:'ceremony',scene:'aisle',speaker:'司仪',text:s.officiant_line},{kind:'choice',id:'vow',scene:'aisle',text:s.vow_prompt,choices:s.vow_choices},{kind:'narrator',scene:'vow',text:s.vow_narration},{kind:'role',scene:'vow',text:s.vow_line},{kind:'action',scene:'vow',text:'他双手合起完整的誓词纸，随后轻轻抬起你的手，目光停在你的手背上。',label:'把手背交给他'},{kind:'narrator',scene:'kiss',text:s.kiss_narration},{kind:'role',scene:'kiss',text:s.kiss_line},{kind:'action',scene:'kiss',text:'他从你的手背前直起身，婚戒正安静地躺在掌心。',label:'看向他掌心的戒指'},{kind:'choice',id:'ring',scene:'ring',text:s.ring_prompt,choices:s.ring_choices},{kind:'narrator',scene:'ring',text:s.ring_narration},{kind:'role',scene:'ring',text:s.ring_line},{kind:'narrator',scene:'embrace',text:s.blessing_narration},{kind:'ceremony',scene:'embrace',speaker:'司仪',text:s.blessing_line},{kind:'narrator',scene:'embrace',text:s.ending_narration},{kind:'role',scene:'embrace',text:s.ending_line},{kind:'finish',scene:'embrace',text:simulation?'模拟仪式到这里结束，所有内容都只停留在本次预览中。':'仪式结束了，你们的名字将一起写进今天。',label:simulation?'模拟签下婚书':'共同签下现代婚书'}];}
function weddingCurrent(){return W.session&&W.session.items[W.session.index];}
function weddingChoiceHTML(item){return '<div class="wedding-choice">'+item.choices.map((x,i)=>'<button onclick="event.stopPropagation();weddingChoose('+i+')">'+esc(x.text)+'</button>').join('')+'</div>';}
function weddingActionHTML(item){return '<div class="wedding-action"><button onclick="event.stopPropagation();weddingAdvance()">'+esc(item.label)+'</button></div>';}
function weddingEnsureStage(c){const root=weddingEnsureRoot();if(W.stageReady&&document.getElementById('weddingStage'))return;const chinese=W.session&&W.session.style==='chinese',opening=W.opening?' wedding-stage-opening':'';root.innerHTML='<section class="wedding-stage '+(chinese?'wedding-stage-chinese':'wedding-stage-modern')+opening+'" id="weddingStage" onclick="weddingAdvance()"><div class="wedding-art-stack"><div class="wedding-art" data-layer="0"></div><div class="wedding-art" data-layer="1"></div></div>'+weddingPetals()+'<div class="wedding-opening-veil" aria-hidden="true"></div><div class="wedding-topbar"><span class="wedding-topbar-spacer" aria-hidden="true"></span><div class="wedding-topbar-center"><small>'+(chinese?'囍 · 良 辰 吉 时':'OUR WEDDING')+'</small><b>'+esc(weddingRoleName(c))+'</b></div><span class="wedding-topbar-spacer" aria-hidden="true"></span></div><div class="wedding-dialog-host" id="weddingDialogHost"></div></section>';W.stageReady=true;W.scene='';W.activeLayer=0;W.opening=false;}
function weddingSetScene(scene){if(W.scene===scene)return;const layers=document.querySelectorAll('#weddingStage .wedding-art');if(layers.length<2)return;const scenes=weddingScenes(W.session&&W.session.style),first=weddingSceneOrder(W.session&&W.session.style)[0],next=W.scene?1-W.activeLayer:0,old=W.activeLayer,nextEl=layers[next],oldEl=layers[old],src=W.sceneImages[scene]||scenes[scene]||scenes[first];clearTimeout(W.sceneTimer);nextEl.className='wedding-art wedding-art-'+scene;nextEl.style.backgroundImage="url('"+String(src).replace(/'/g,'%27')+"')";void nextEl.offsetWidth;if(W.scene&&oldEl!==nextEl)oldEl.classList.remove('active');nextEl.classList.add('active');W.activeLayer=next;W.scene=scene;if(oldEl!==nextEl)W.sceneTimer=setTimeout(()=>{oldEl.className='wedding-art';oldEl.style.backgroundImage='';},1400);}
function weddingRenderStory(){const s=W.session,item=weddingCurrent(),c=s&&getC(s.cid);if(!s||!item||!c)return weddingClose();weddingEnsureStage(c);weddingSetScene(item.scene||'welcome');clearTimeout(W.typingTimer);W.typingDone=!['role','narrator','ceremony'].includes(item.kind);const speaker=item.kind==='role'?weddingRoleName(c):item.kind==='narrator'?'旁白':item.kind==='ceremony'?(item.speaker||'司仪'):'此刻',controls=item.kind==='choice'?weddingChoiceHTML(item):['action','finish'].includes(item.kind)?weddingActionHTML(item):'<div class="wedding-next"><span>点击继续</span><i></i></div>',host=document.getElementById('weddingDialogHost');host.innerHTML='<div class="wedding-dialog wedding-dialog-'+esc(item.kind)+' '+(item.kind==='narrator'?'narrator':item.kind==='ceremony'?'ceremony':'')+'"><div class="wedding-speaker">'+esc(speaker)+'</div><div class="wedding-dialog-text" id="weddingLine">'+(['role','narrator','ceremony'].includes(item.kind)?'':esc(item.text))+'</div>'+controls+'</div>';if(host.animate)host.animate([{opacity:.68,transform:'translateY(5px)'},{opacity:1,transform:'translateY(0)'}],{duration:260,easing:'ease-out'});if(['role','narrator','ceremony'].includes(item.kind))weddingTypeLine(item.text);}
function weddingTypeLine(text){const el=document.getElementById('weddingLine'),chars=Array.from(String(text||''));if(!el)return;let i=0;el.textContent='';W.typingDone=false;const tick=()=>{if(!el.isConnected)return;const step=i<8?1:2;i=Math.min(chars.length,i+step);el.textContent=chars.slice(0,i).join('');if(i<chars.length)W.typingTimer=setTimeout(tick,31);else W.typingDone=true;};tick();}
function weddingReveal(){const item=weddingCurrent(),el=document.getElementById('weddingLine');clearTimeout(W.typingTimer);if(el&&item)el.textContent=item.text||'';W.typingDone=true;}
function weddingTransitionToCertificate(){const s=W.session,stage=document.getElementById('weddingStage');if(!s||W.busy)return;W.busy=true;const chinese=s.style==='chinese',veil=document.createElement('div');veil.className='wedding-certificate-transition '+(chinese?'chinese':'modern');veil.innerHTML='<span>'+(chinese?'礼 成':'CEREMONY COMPLETE')+'</span><b>'+(chinese?'共书婚约':'Together, we write our promise')+'</b><i></i>';(stage||weddingEnsureRoot()).appendChild(veil);requestAnimationFrame(()=>veil.classList.add('show'));setTimeout(()=>{W.busy=false;weddingFinish();},1850);}
async function weddingAdvance(){const s=W.session,item=weddingCurrent();if(!s||!item||W.busy)return;if(!W.typingDone){weddingReveal();return;}if(item.kind==='choice')return;if(item.kind==='finish'){weddingTransitionToCertificate();return;}try{if(typeof audioUnlock==='function')audioUnlock();}catch(_){}s.index++;if(s.index>=s.items.length)return weddingTransitionToCertificate();weddingRenderStory();}
function weddingChoose(i){const s=W.session,item=weddingCurrent();if(!s||!item||item.kind!=='choice')return;const pick=Math.max(0,Math.min(item.choices.length-1,i)),choice=item.choices[pick];s.choices[item.id||('choice_'+s.index)]={index:pick,text:choice.text};s.items.splice(s.index+1,0,{kind:'role',scene:item.scene,text:choice.response,branch:true});s.index++;save();weddingRenderStory();}
function weddingExitAsk(){if(!W.session)return weddingClose();openModal('<h3>暂时离开婚礼？</h3><div class="hint">已经生成的台词和画面缓存会保留，但未完成的仪式不会写入重要记忆。</div><div class="btns"><button class="btn g" onclick="closeModal()">继续仪式</button><button class="btn p" onclick="closeModal();weddingClose()">离开</button></div>');}
function weddingChoiceSummary(s){return Object.keys(s.choices||{}).map(k=>{const x=s.choices[k];return(k==='hand'?'牵手选择':k==='vow'?'誓言选择':'戒指选择')+'“'+(x&&x.text||'')+'”';}).join('，');}
function weddingChineseDay(at){const d=new Date(at||Date.now());return d.getFullYear()+'年'+String(d.getMonth()+1).padStart(2,'0')+'月'+String(d.getDate()).padStart(2,'0')+'日';}
function weddingStyleName(style){return style==='chinese'?'现实中的中式婚礼':'现实中的现代婚礼';}
function weddingSaveMemory(c,s,record){if(!c||!record)return'';c._weddingMemoryIds=Array.isArray(c._weddingMemoryIds)?c._weddingMemoryIds:[];if(c._weddingMemoryIds.includes(record.id))return'';const day=weddingChineseDay(record.date),city=weddingRoleCity(c),choices=weddingChoiceSummary(s),style=record.style==='chinese'?'chinese':'modern',styleName=style==='chinese'?'中式':'现代',facts=style==='chinese'?'我亲手掀开花轿帘迎她下轿，与她牵红绣球依次完成一拜天地、二拜高堂与夫妻对拜，随后与她碰杯敬酒，最后用喜秤为她挑起红盖头并共同签下中式婚书。':'我们牵手走过花路，我双手宣读誓言、亲吻她的手背、为她的左手无名指戴上婚戒，最后正面拥抱礼成并共同签下现代婚书。',text='我和'+(s.brideName||((S.me&&S.me.name)||'她'))+'在'+day+'、在'+city+'正式举行了一场现实中的'+styleName+'婚礼，我清楚记得这不是'+(style==='chinese'?'现代':'中式')+'婚礼。'+facts+(choices?'我也记得她当时的'+choices+'。':'')+'婚书结语是：“'+s.script.certificate_vow+'”';c._weddingMemoryIds.push(record.id);c._weddingMemoryIds=c._weddingMemoryIds.slice(-20);if(typeof addSummary==='function')addSummary(c,text,5,'','main');else{c.summaries=Array.isArray(c.summaries)?c.summaries:[];c.summaries.push({time:new Date().toLocaleString('zh-CN'),ts:Date.now(),text,imp:5,confidence:1,accountId:'main'});}return text;}
function weddingMarkMarried(c,record){if(!c||!record)return null;if(!S.couple||S.couple.cid!==c.id)S.couple=typeof coupleDefaultState==='function'?coupleDefaultState(c.id):{cid:c.id,startDate:weddingLocalDay(record.date),anniversaries:[]};const cp=S.couple,style=record.style==='chinese'?'chinese':'modern';cp.married=true;cp.relationship='夫妻';cp.marriedAt=cp.marriedAt||record.date;cp.marriageDate=cp.marriageDate||weddingLocalDay(record.date);cp.marriageStyle=style;cp.marriageStyles=Array.isArray(cp.marriageStyles)?cp.marriageStyles:[];if(!cp.marriageStyles.includes(style))cp.marriageStyles.push(style);cp.marriageRecordId=record.id;cp.anniversaries=Array.isArray(cp.anniversaries)?cp.anniversaries:[];if(!cp.anniversaries.some(x=>x&&x.title==='结婚纪念日'))cp.anniversaries.push({date:cp.marriageDate,title:'结婚纪念日'});const rel=String(c.relation||'').trim();if(!/夫妻|已婚|丈夫|妻子|老公|老婆/.test(rel))c.relation=rel?(rel+'；已结为夫妻'):'夫妻';return cp;}
function weddingCoupleCollectionHTML(cp,c,SEC,HD,ROSE,GOLD){const seen={},records=weddingState().records.filter(x=>x&&x.cid===c.id&&!seen[x.style||'modern']&&(seen[x.style||'modern']=true)),rows=records.map(r=>'<button class="wedding-collection-row" onclick="weddingOpenCertificateRecord(\''+c.id+'\',\''+r.id+'\')"><span><small>'+esc((r.style==='chinese'?'CHINESE':'MARRIAGE')+' CERTIFICATE')+'</small><b>'+esc(r.style==='chinese'?'中式婚书':'现代婚书')+' · '+esc(weddingLocalDay(r.date).replace(/-/g,' / '))+'</b><em>'+esc(weddingStyleName(r.style))+'</em></span><i>打开婚书 ›</i></button>').join('');return '<div id="cou_wedding_collection" '+SEC+'>'+HD('file','婚书收藏夹',GOLD,cp.married?'<span class="wedding-married-badge">夫妻</span>':'')+(rows||'<div class="empty" style="padding:14px">完成婚礼后，每种婚礼的婚书会各收藏一份</div>')+'</div>';}
async function weddingAfterMessage(c,s,record,memory){if(!c||!record||record.afterMessageSent)return;record.afterMessageSent=true;save();const chinese=record.style==='chinese';let text=chinese?'礼成了。方才每一拜、每一次相望，我都会记得。往后你我便是夫妻。':'仪式结束了，可我现在还是只想再跟你说一句：今天的每一秒，我都会记一辈子。';try{const prior=msgs(c.id).filter(x=>x&&x._weddingAfter&&x.content).slice(-4).map(x=>'“'+x.content+'”').join('、'),facts=chinese?'我们的现实中式婚礼刚刚结束：我迎她下轿，和她牵红绣球，依次完成一拜天地、二拜高堂、夫妻对拜，与她碰杯敬酒，最后用喜秤挑起盖头并签下中式婚书。':'我们的现实现代婚礼刚刚结束：我双手拿完整誓词纸宣读誓言，亲吻她的手背，为她左手无名指戴上戒指，最后正面拥抱礼成并签下现代婚书。',prompt=facts+'她的选择：'+(weddingChoiceSummary(s)||'她郑重完成了每一步')+'。婚书结语：“'+s.script.certificate_vow+'”。现在你回到微信，主动给她发一条婚礼结束后的私人消息。你必须清楚这是'+(chinese?'中式':'现代')+'婚礼并符合人设；写1到2条短微信，共20到80字，不要旁白、括号动作、标签、Markdown，不要说这是游戏或系统。'+(prior?'你之前婚礼后发过这些话：'+prior+'。这一次必须换一个细节、角度和句式。':'');const raw=await chatAPI([{role:'system',content:buildSystem(c)},{role:'user',content:prompt}],{max:220,temp:.86,complete:true});const cleaned=String(typeof roleVisibleEnvelopeText==='function'?roleVisibleEnvelopeText(raw):raw||'').replace(/\[[^\]]*\]|【[^】]*】/g,'').replace(/\s+/g,' ').trim();if(cleaned)text=cleaned.slice(0,100);}catch(_){}const m={role:'assistant',type:'text',content:text,time:Date.now(),id:uid(),_weddingAfter:record.id,_weddingStyle:record.style};msgs(c.id).push(m);record.afterMessageAt=m.time;save();try{notifyIncoming(c,m);}catch(_){}if(cur().p==='chat'&&cur().id===c.id)refreshChatMessages(c.id);}
function weddingChineseCertificateCard(bride,groom,date,vow){return '<div class="wedding-cert-card wedding-cert-card-chinese"><div class="wedding-chinese-cert-content"><h2>婚书</h2><div class="wedding-chinese-vows"><p>两姓缔结良缘，一堂结同心</p><p>鸾凤和鸣，愿有岁月可回首</p><p>且以深情共白头</p><p>敬以情深，恩爱相携</p><p>相敬如宾，举案齐眉</p><p>同担风雨，共度朝夕</p><p>和顺门庭，孝友睦邻</p><p>珠联璧合，永结同心</p></div><div class="wedding-chinese-date">此证 · '+esc(date)+'</div><p class="wedding-chinese-vow">'+esc(vow)+'</p><div class="wedding-chinese-names"><span>'+esc(bride)+'</span><i>与</i><span>'+esc(groom)+'</span></div></div></div>';}
function weddingShowCertificate(c,record,allowReplay,simulation){const d=new Date(record.date||Date.now()),date=d.getFullYear()+' / '+String(d.getMonth()+1).padStart(2,'0')+' / '+String(d.getDate()).padStart(2,'0'),vow=record.vow||'愿往后的每一次欢笑与风雨，都有我在你身旁。',bride=record.brideName||W.session&&W.session.brideName||S.me&&S.me.name||'我',groom=record.groomName||W.session&&W.session.groomName||weddingRoleOriginalName(c),style=record.style==='chinese'?'chinese':'modern',styleName=style==='chinese'?'中式':'现代',actions=simulation?'<button class="primary" onclick="weddingReplay()">再模拟一次</button><button onclick="weddingClose()">结束模拟</button>':allowReplay?'<button class="primary" onclick="weddingRegenerate(\''+c.id+'\',\''+style+'\')">重新生成'+styleName+'婚礼</button><button onclick="weddingClose()">回到小手机</button>':'<button class="primary" onclick="weddingClose()">回到情侣空间</button>',note=simulation?'模拟模式：本次不会收藏婚书、写入记忆、改变关系或发送婚后消息':allowReplay?'重新生成会覆盖这一种婚礼的旧演出；现代与中式各自独立保存。':'',modern='<div class="wedding-cert-card"><div class="wedding-cert-content"><h2>Marriage Certificate</h2><div class="wedding-cert-divider"><i></i></div><p>On this day, <b>'+esc(date)+'</b>, we joyfully unite<br><strong>'+esc(bride)+'</strong> and <strong>'+esc(groom)+'</strong> in marriage.</p><p>Together, we choose each other as life partners.</p><div class="wedding-cert-divider"><i></i></div><p>We promise to love and respect one another,<br>to listen with patience, forgive with grace,<br>and stand together through every season of life.</p><p>We will celebrate each other\'s dreams,<br>share both joy and sorrow,<br>and make a home wherever we are together.</p><div class="wedding-cert-divider"><i></i></div><p>With family and friends as witnesses,<br>we affirm this bond with love and gratitude.</p><p class="wedding-cert-vow">'+esc(vow)+'</p><div class="wedding-cert-ornament"><i></i></div><div class="wedding-cert-signatures"><span><i></i><small>Signature</small></span><span><i></i><small>Signature</small></span></div><div class="wedding-cert-bottom-names"><span>'+esc(bride)+'</span><i>&amp;</i><span>'+esc(groom)+'</span></div></div></div>',card=style==='chinese'?weddingChineseCertificateCard(bride,groom,date,vow):modern;W.view='certificate';weddingMount('<section class="wedding-certificate wedding-certificate-'+style+' '+(simulation?'wedding-certificate-simulation':'')+'">'+weddingCertificatePetals()+'<button class="wedding-icon-btn wedding-cert-close" onclick="weddingClose()" aria-label="退出">×</button>'+(simulation?'<div class="wedding-simulation-badge">SIMULATION · 不保存</div>':'')+card+'<div class="wedding-cert-actions">'+actions+'</div>'+(note?'<div class="wedding-after-note">'+esc(note)+'</div>':'')+'</section>');requestAnimationFrame(()=>{if(style==='modern'){weddingFitCertificateTitle();setTimeout(weddingFitCertificateTitle,180);setTimeout(weddingFitCertificateTitle,500);}});}
function weddingOpenCertificateRecord(cid,recordId){const c=getC(cid),record=weddingState().records.find(x=>x&&x.id===recordId&&x.cid===cid);if(!c||!record)return;W.session=null;weddingMusicStop();weddingShowCertificate(c,record,false);}
function weddingFinish(){const s=W.session,c=s&&getC(s.cid);if(!s||!weddingEligibleRole(c))return weddingClose();const style=weddingStyleKey(s.style);if(s.simulation){s.saved=true;return weddingShowCertificate(c,{id:'simulation',cid:c.id,style,date:Date.now(),choices:s.choices,vow:s.script.certificate_vow,formalwear:s.formalwear,generated:s.generated,brideName:s.brideName,groomName:s.groomName},true,true);}const st=weddingState(),ceremonyAt=Number.isFinite(+s.ceremonyAt)?+s.ceremonyAt:Date.now();let record=s.recordId&&st.records.find(x=>x&&x.id===s.recordId);if(!s.saved){record=st.records.find(x=>x&&x.cid===c.id&&(x.style||'modern')===style)||{id:'wed_'+style+'_'+weddingHash(c.id),cid:c.id,style,createdAt:Date.now()};Object.assign(record,{style,date:record.date||ceremonyAt,updatedAt:Date.now(),choices:s.choices,vow:s.script.certificate_vow,formalwear:s.formalwear,generated:s.generated,brideName:s.brideName,groomName:s.groomName,styleLabel:weddingStyleName(style)});st.records=st.records.filter(x=>x&&x!==record&&(x.cid!==c.id||(x.style||'modern')!==style));st.records.unshift(record);st.records=st.records.slice(0,12);weddingMarkMarried(c,record);const memory=weddingSaveMemory(c,s,record),runRecord={id:'wedrun_'+Date.now(),cid:c.id,style,date:ceremonyAt,certificateId:record.id};s.saved=true;s.recordId=record.id;save();setTimeout(()=>weddingAfterMessage(c,s,runRecord,memory),900);}else if(record)weddingMarkMarried(c,record);weddingShowCertificate(c,record||{style,date:ceremonyAt,vow:s.script.certificate_vow,brideName:s.brideName,groomName:s.groomName},true,false);}
function weddingReplay(){if(!W.session)return weddingOpen();weddingMusicStop();W.session.index=0;W.session.items=weddingBuildItems(W.session.script,!!W.session.simulation,W.session.style);W.session.choices={};W.session.saved=false;W.session.recordId='';W.session.startedAt=Date.now();W.stageReady=false;W.scene='';W.opening=true;const c=getC(W.session.cid);if(c)weddingShowNameCard(c);}
function weddingDebugState(){return{view:W.view,scene:W.scene,bgm:W.bgm?{src:W.bgm.src,loop:W.bgm.loop,paused:W.bgm.paused}:null,session:W.session?{cid:W.session.cid,index:W.session.index,formalwear:W.session.formalwear,simulation:!!W.session.simulation}:null,invitationJobs:Object.keys(weddingInviteJobs)};}
function weddingRegister(){try{APPDEFS.wedding={e:'💍',c:'linear-gradient(135deg,#d9c0aa,#8f6f5b)',t:'婚礼',icon:'couple'};APPRUN.wedding=()=>weddingOpen();if(typeof APP_NLWORDS==='object')APP_NLWORDS.wedding=['婚礼','结婚','婚书','七夕'];if(typeof homeLayoutInit==='function'){homeLayoutInit();save(250);}if(cur&&cur().p==='home')render();}catch(e){console.warn('wedding register failed',e);}if(location.hash==='#wedding-preview')setTimeout(()=>weddingOpen(),350);if(location.hash==='#wedding-invitation-preview')setTimeout(()=>{const c=weddingInvitationRole();if(c){weddingSendInvitation(c,'preview');openChat(c.id);setTimeout(()=>refreshChatMessages(c.id),60);}},350);weddingResetQixiInvitationOnce();setTimeout(()=>{weddingResumeInvitations();weddingAutoInvitation(Date.now());},900);clearInterval(weddingCountdownTimer);weddingCountdownTimer=setInterval(weddingInvitationTick,1000);}
Object.assign(window,{WEDDING_SCENE_CONTRACTS,WEDDING_CHINESE_SCENE_CONTRACTS,weddingOpen,weddingClose,weddingOfflineEntryHTML,weddingInviteCardHTML,weddingHandleInviteRequest,weddingAutoInvitation,weddingSendInvitation,weddingScheduleCalendarEvent,weddingCalendarTick,weddingChooseInvitationStyle,weddingPrepareInvitation,weddingOpenReadyInvite,weddingRegenerate,weddingSelectRole,weddingStart,weddingStartSimulation,weddingBeginCeremony,weddingAdvance,weddingChoose,weddingExitAsk,weddingFinish,weddingReplay,weddingAppearanceProfile,weddingBuildImagePrompt,weddingLineMatchesScene,weddingVerifyImage,weddingCoupleCollectionHTML,weddingOpenCertificateRecord,weddingDebugState});
setTimeout(weddingRegister,0);
